"use strict";(globalThis.webpackChunkpaper=globalThis.webpackChunkpaper||[]).push([[311],{2827:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/test","metadata":{"permalink":"/paper/economy/test","source":"@site/economy/test.md","title":"\uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c \uac00\uaca9\uc740 \uc65c \ub0b4\ub824\uac08\uae4c","description":"\uc774\ubbf8 \uc815\ud574\uc9c4 \uc774\uc790\ub97c \uc8fc\ub294 \ucc44\uad8c\uc758 \uac00\uce58\ub294 \uc2dc\uc7a5 \uae08\ub9ac\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4.","date":"2026-10-28T00:00:00.000Z","tags":[],"readingTime":2.125,"hasTruncateMarker":false,"authors":[],"frontMatter":{"title":"\uae08\ub9ac\uac00 \uc624\ub974\uba74 \ucc44\uad8c \uac00\uaca9\uc740 \uc65c \ub0b4\ub824\uac08\uae4c","description":"\uc774\ubbf8 \uc815\ud574\uc9c4 \uc774\uc790\ub97c \uc8fc\ub294 \ucc44\uad8c\uc758 \uac00\uce58\ub294 \uc2dc\uc7a5 \uae08\ub9ac\uc640 \ubc18\ub300\ub85c \uc6c0\uc9c1\uc778\ub2e4.","image":"https://picsum.photos/seed/paper-economy/800/500","date":"2026-10-28T00:00:00.000Z"},"unlisted":false},"content":"\uacbd\uc81c \ub274\uc2a4\uc5d0\uc11c \\"\uae08\ub9ac \uc778\uc0c1\uc73c\ub85c \ucc44\uad8c \uac00\uaca9 \ud558\ub77d\\"\uc774\ub77c\ub294 \ubb38\uc7a5\uc744 \uc790\uc8fc \ubcf8\ub2e4. \ucc98\uc74c\uc5d0\ub294 \uae08\ub9ac\uac00 \uc624\ub974\uba74 \uc774\uc790\ub97c \ub354 \ubc1b\uc73c\ub2c8 \ucc44\uad8c\uc774 \uc88b\uc544\uc9c0\ub294 \uac83 \uc544\ub2cc\uac00 \uc2f6\uc5c8\ub294\ub370, \ud575\uc2ec\uc740 **\uc774\ubbf8 \ubc1c\ud589\ub41c \ucc44\uad8c\uc758 \uc774\uc790\ub294 \uace0\uc815\ub418\uc5b4 \uc788\ub2e4**\ub294 \uc810\uc774\uc5c8\ub2e4.\\n\\n## \ud83d\udccc \ucc44\uad8c\uc758 \uae30\ubcf8 \uad6c\uc870\\n\\n\ucc44\uad8c\uc740 \ub3c8\uc744 \ube4c\ub824\uc8fc\uace0 \ubc1b\ub294 \ucc28\uc6a9\uc99d\uc774\ub2e4. \ubc1c\ud589\ud560 \ub54c \ub9cc\uae30\uc640 \uc774\uc790(\ucfe0\ud3f0)\uac00 \uc815\ud574\uc9c0\uace0, \uadf8 \ub4a4\ub85c \uc2dc\uc7a5 \uae08\ub9ac\uac00 \uc5b4\ub5bb\uac8c \ubc14\ub00c\ub4e0 \uc57d\uc18d\ub41c \uae08\uc561\uc740 \uadf8\ub300\ub85c\ub2e4.\\n\\n- **\uc561\uba74\uac00**: \ub9cc\uae30\uc5d0 \ub3cc\ub824\ubc1b\ub294 \uc6d0\uae08\\n- **\ucfe0\ud3f0 \uae08\ub9ac**: \ubc1c\ud589 \ub54c \uc815\ud574\uc9c4 \uc774\uc790\uc728\\n- **\uc2dc\uc7a5 \uae08\ub9ac**: \uc9c0\uae08 \uc0c8\ub85c \ub3c8\uc744 \ube4c\ub824\uc904 \ub54c \ubc1b\uc744 \uc218 \uc788\ub294 \uc774\uc790\uc728\\n\\n## \ud83e\uddee \uc22b\uc790\ub85c \ubcf4\uae30\\n\\n\ub9cc\uae30 1\ub144, \uc561\uba74\uac00 10,000\uc6d0, \ucfe0\ud3f0 \uae08\ub9ac 3%\uc778 \ucc44\uad8c\uc740 1\ub144 \ub4a4 10,300\uc6d0\uc744 \ub3cc\ub824\uc900\ub2e4. \uc774 \ucc44\uad8c\uc744 \uc9c0\uae08 \uc5bc\ub9c8\uc5d0 \uc0ac\uc57c \ud560\uc9c0\ub294 \uc2dc\uc7a5 \uae08\ub9ac\ub85c \ud560\uc778\ud574\uc11c \uad6c\ud55c\ub2e4.\\n\\n| \uc2dc\uc7a5 \uae08\ub9ac | \uacc4\uc0b0 | \uc624\ub298\uc758 \ucc44\uad8c \uac00\uaca9 |\\n| --- | --- | --- |\\n| 2% | 10,300 \xf7 1.02 | \uc57d 10,098\uc6d0 |\\n| 3% | 10,300 \xf7 1.03 | 10,000\uc6d0 |\\n| 4% | 10,300 \xf7 1.04 | \uc57d 9,904\uc6d0 |\\n\\n\uc2dc\uc7a5 \uae08\ub9ac\uac00 4%\ub85c \uc624\ub974\uba74 \uc0c8 \ucc44\uad8c\uc740 4%\ub97c \uc8fc\ub294\ub370, 3%\uc9dc\ub9ac \uae30\uc874 \ucc44\uad8c\uc744 \uc81c\uac12\uc5d0 \uc0b4 \uc0ac\ub78c\uc740 \uc5c6\ub2e4. \uadf8\ub798\uc11c \uac00\uaca9\uc774 \ub0b4\ub824\uac00\uc57c \uac70\ub798\uac00 \ub41c\ub2e4.\\n\\n## \ud83d\udd01 \uc815\ub9ac\\n\\n> \uae08\ub9ac \u2191 \u2192 \uae30\uc874 \ucc44\uad8c\uc758 \ub9e4\ub825 \u2193 \u2192 \ucc44\uad8c \uac00\uaca9 \u2193\\n\\n\ub9cc\uae30\uac00 \uae38\uc218\ub85d \uace0\uc815\ub41c \uc774\uc790\ub97c \ubc1b\ub294 \uae30\uac04\uc774 \uae38\uc5b4\uc11c \uae08\ub9ac \ubcc0\ud654\uc5d0 \uac00\uaca9\uc774 \ub354 \ud06c\uac8c \ud754\ub4e4\ub9b0\ub2e4. \uc774\uac78 **\ub4c0\ub808\uc774\uc158**\uc774\ub77c\uace0 \ubd80\ub974\ub294\ub370, \ub2e4\uc74c \uae00\uc5d0\uc11c \uc815\ub9ac\ud574 \ubcf4\uae30."}]}}')}}]);